INSERT INTO Language_en_US(Tag,Text) VALUES
('TXT_KEY_VILTRUM_LEADER','Grand Regent Thragg'),
('TXT_KEY_VILTRUM_LEADER_PEDIA','Thragg, Grand Regent of the Viltrum Empire, rules through absolute strength and the preservation of Viltrumite blood. His empire must survive a catastrophe that military force cannot defeat.'),
('TXT_KEY_VILTRUM_CIV','The Viltrum Empire'),
('TXT_KEY_VILTRUM_SHORT','Viltrum'),
('TXT_KEY_VILTRUM_ADJECTIVE','Viltrumite'),
('TXT_KEY_VILTRUM_CIV_PEDIA','The Viltrum Empire conquered countless worlds, sustained by genetically extraordinary warriors. The Great Purge forged its ideology; the Scourge Virus nearly extinguished its people. Conventional subject armies and a handful of survivors must rebuild the dominion.'),
('TXT_KEY_VILTRUM_STRATEGY','Conquer aggressively before the guaranteed Scourge. Each 1300-Production Viltrumite is an enormous investment: keep conventional Infantry, artillery, anti-air and aircraft. Breeding Complexes protect citizens. Stockpile Gold and position defensively after Replaceable Parts. Quarantine preserves more survivors; continuing the crusade creates powerful Last Purebloods at devastating risk.'),
('TXT_KEY_VILTRUM_WARRIOR','Viltrumite Warrior'),
('TXT_KEY_VILTRUM_WARRIOR_PEDIA','A flying strategic breakthrough warrior. One costs about 3.47 ordinary Infantry. Biological Bloodline, Flight, March, Relentless Execution and Planetbreaker are free. Only genuine outbreak survivors receive the strongest survivor promotions.'),
('TXT_KEY_VILTRUM_WARRIOR_STRATEGY','Conquer aggressively before the guaranteed Scourge. Each 1300-Production Viltrumite is an enormous investment: keep conventional Infantry, artillery, anti-air and aircraft. Breeding Complexes protect citizens. Stockpile Gold and position defensively after Replaceable Parts. Quarantine preserves more survivors; continuing the crusade creates powerful Last Purebloods at devastating risk.'),
('TXT_KEY_VILTRUM_WARRIOR_HELP','82 Strength, 3 Movement, 1300 Production; Replaceable Parts. Ignores terrain costs, crosses mountains and coasts, deploys 7 tiles from friendly territory, attacks after deployment, and captures cities. Heals 35 HP on personal capture. Relentless Execution: +15% against targets below 50 HP; Planetbreaker: +20% against cities below half health.'),
('TXT_KEY_VILTRUM_AUXILIARY','Auxiliary Infantry'),
('TXT_KEY_VILTRUM_AUXILIARY_PEDIA','Conventional subject-world Infantry. Retains the installed ruleset Infantry statistics, requirements, upgrades and model. Auxiliaries are unaffected by biological Scourge casualties.'),
('TXT_KEY_VILTRUM_COMPLEX','Viltrumite Breeding Complex'),
('TXT_KEY_VILTRUM_COMPLEX_PEDIA','Replaces the Military Academy and retains its ruleset effects. Adds 15 XP, 2 Production, 1 Food and 5% military Production. First construction grants one citizen once per original city. Each Complex protects one additional citizen during the Scourge.'),
('TXT_KEY_VILTRUM_COMPLEX_STRATEGY','Build before the Scourge to protect population and condition land troops.'),
('TXT_KEY_VILTRUM_COMPLEX_HELP','Military Academy effects plus 15 XP, +2 Production, +1 Food, +5% military Production. First construction: +1 Population. Trained land troops gain Imperial Conditioning. Protects one additional citizen during the Scourge.'),
('TXT_KEY_VILTRUM_BLOODLINE','Viltrumite Bloodline'),
('TXT_KEY_VILTRUM_BLOODLINE_HELP','Biological marker retained through upgrades; targeted by the Scourge.'),
('TXT_KEY_VILTRUM_FLIGHT','Viltrumite Flight'),
('TXT_KEY_VILTRUM_FLIGHT_HELP','Ignore terrain costs; cross mountains and shallow water; deploy 7 tiles and attack after deployment.'),
('TXT_KEY_VILTRUM_EXECUTION','Relentless Execution'),
('TXT_KEY_VILTRUM_EXECUTION_HELP','+15% combat strength against an enemy combat unit below 50 HP.'),
('TXT_KEY_VILTRUM_PLANETBREAKER','Planetbreaker'),
('TXT_KEY_VILTRUM_PLANETBREAKER_HELP','+20% when attacking a city below 50% HP; heal 35 HP on personal city capture.'),
('TXT_KEY_VILTRUM_EXECUTION_ACTIVE','Relentless Execution bonus'),
('TXT_KEY_VILTRUM_EXECUTION_ACTIVE_HELP','Temporary target-conditioned combat modifier.'),
('TXT_KEY_VILTRUM_PLANET_ACTIVE','Planetbreaker bonus'),
('TXT_KEY_VILTRUM_PLANET_ACTIVE_HELP','Temporary wounded-city attack modifier.'),
('TXT_KEY_VILTRUM_MOMENTUM','Imperial Momentum'),
('TXT_KEY_VILTRUM_MOMENTUM_HELP','First conquests activate 8 turns of +15% military Production, +3 XP to trained military units and +5% city attack. Additional first conquests extend by 3 up to 18 remaining turns. Quarantine suspends all conquest rewards.'),
('TXT_KEY_VILTRUM_CONDITIONING','Imperial Conditioning'),
('TXT_KEY_VILTRUM_CONDITIONING_HELP','+5% strength outside friendly territory. Healing +1 HP in friendly or neutral territory (rounded native approximation of 5%).'),
('TXT_KEY_VILTRUM_CONDITION_ACTIVE','Conditioned abroad'),
('TXT_KEY_VILTRUM_CONDITION_ACTIVE_HELP','+5% outside friendly territory.'),
('TXT_KEY_VILTRUM_HARDENED','Scourge-Hardened'),
('TXT_KEY_VILTRUM_HARDENED_HELP','True quarantine survivor: +10% strength, +1 sight, native healing +4 friendly/+2 neutral/+2 enemy HP (approximately 20%).'),
('TXT_KEY_VILTRUM_PUREBLOOD','Last Pureblood'),
('TXT_KEY_VILTRUM_PUREBLOOD_HELP','True crusade survivor: +20% strength, +1 move, Blitz, +20% combat XP. +20% strength below 50 HP; fully heals on personal enemy original-capital capture.'),
('TXT_KEY_VILTRUM_PURE_ACTIVE','Last Pureblood fury'),
('TXT_KEY_VILTRUM_PURE_ACTIVE_HELP','+20% strength while below 50 HP.'),
('TXT_KEY_VILTRUM_GENOME','Hardened Genome'),
('TXT_KEY_VILTRUM_GENOME_HELP','Post-outbreak Viltrumite trained by Viltrum: +5% strength.'),
('TXT_KEY_VILTRUM_WARNING','Impossible Illness'),
('TXT_KEY_VILTRUM_WARNING_HELP','Native healing -5 friendly/-3 neutral/-3 enemy HP (approximately 25% of normal field healing).'),
('TXT_KEY_VILTRUM_QUARANTINE','Total Quarantine'),
('TXT_KEY_VILTRUM_QUARANTINE_HELP','Native healing -10 friendly/-5 neutral/-5 enemy HP (approximately 50% of normal field healing).'),
('TXT_KEY_VILTRUM_NO_HEAL','Dying Empire'),
('TXT_KEY_VILTRUM_NO_HEAL_HELP','Cannot passively heal outside friendly territory.'),
